Here’s a **clean and simple recursive binary search** program in C 👇  

```c
#include <stdio.h>

// Recursive binary search function
int binarySearch(int arr[], int left, int right, int target) {
    if (left > right)
        return -1; // not found

    int mid = (left + right) / 2;

    if (arr[mid] == target)
        return mid; // found
    else if (arr[mid] > target)
        return binarySearch(arr, left, mid - 1, target); // search left side
    else
        return binarySearch(arr, mid + 1, right, target); // search right side
}

int main() {
    int arr[100], n, target;

    printf("Enter number of elements: ");
    scanf("%d", &n);

    printf("Enter %d sorted elements: ", n);
    for (int i = 0; i < n; i++)
        scanf("%d", &arr[i]);

    printf("Enter element to search: ");
    scanf("%d", &target);

    int result = binarySearch(arr, 0, n - 1, target);

    if (result == -1)
        printf("Element not found\n");
    else
        printf("Element found at index %d\n", result);

    return 0;
}
```

